const { spawn } = require('child_process');
const fetch = require('node-fetch');
const fs = require('fs');
const path = require('path');

// Configuration
const SERVER_PORT = 3000;
const SERVER_PATH = '/home/user/webhook_server.js';
const REPORT_PATH = '/home/user/webhook_test_report.json';

// Sample purchase payload
const samplePurchase = {
  purchaseId: 'test-order-12345',
  customerEmail: 'test@example.com',
  productName: 'Premium Subscription',
  amount: 99.99
};

let serverProcess;

// Start the server as a child process
function startServer() {
  return new Promise((resolve, reject) => {
    console.log('Starting webhook server...');
    serverProcess = spawn('node', [SERVER_PATH], {
      stdio: 'inherit',
      env: { ...process.env, CROSSMINT_API_KEY: process.env.CROSSMINT_API_KEY || 'test-api-key' }
    });

    serverProcess.on('error', (err) => {
      console.error('Failed to start server:', err);
      reject(err);
    });

    serverProcess.on('exit', (code) => {
      console.log(`Server exited with code ${code}`);
    });

    // Wait a bit for server to start
    setTimeout(() => {
      console.log('Server started');
      resolve();
    }, 1000);
  });
}

// Stop the server
function stopServer() {
  if (serverProcess) {
    console.log('Stopping server...');
    serverProcess.kill();
  }
}

// Test health endpoint
async function testHealth() {
  try {
    console.log('Testing /health endpoint...');
    const response = await fetch(`http://localhost:${SERVER_PORT}/health`);
    const data = await response.json();
    console.log('Health check response:', data);
    return response.ok;
  } catch (error) {
    console.error('Health check failed:', error.message);
    return false;
  }
}

// Test webhook endpoint
async function testWebhook() {
  try {
    console.log('Testing /webhook/purchase endpoint...');
    const response = await fetch(`http://localhost:${SERVER_PORT}/webhook/purchase`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(samplePurchase)
    });
    const data = await response.json();
    console.log('Webhook response:', data);
    return data;
  } catch (error) {
    console.error('Webhook test failed:', error.message);
    return { error: error.message };
  }
}

// Save test report
function saveReport(healthCheck, webhookResponse) {
  const report = {
    health_check: healthCheck,
    webhook_response: webhookResponse,
    timestamp: new Date().toISOString()
  };

  fs.writeFileSync(REPORT_PATH, JSON.stringify(report, null, 2));
  console.log(`Report saved to ${REPORT_PATH}`);
}

// Main test execution
async function runTests() {
  try {
    await startServer();

    // Run health check
    const healthCheck = await testHealth();

    // Run webhook test
    const webhookResponse = await testWebhook();

    // Save report
    saveReport(healthCheck, webhookResponse);

  } catch (error) {
    console.error('Test execution error:', error);
  } finally {
    stopServer();
  }
}

// Run tests and always exit with code 0
runTests().then(() => {
  console.log('Tests completed');
  process.exit(0);
}).catch(() => {
  process.exit(0);
});

